import { watcherEnvSchema } from '../../../apps/watcher/src/config.js';
import { demoEnvSchema } from '../../../apps/demo/src/config.js';
import { facilitatorEnvSchema } from '../../../apps/facilitator/src/config.js';
import { buildOpenApi } from '../../../apps/facilitator/src/http/openapi.js';
import { commandPaths, renderHelp } from '../../cli/src/cli.js';
import { renderApi } from './api-ref.js';
import { renderEnvTable } from './config-ref.js';
import { renderErrors } from './errors.js';

/** Every generated file, relative to the repository root. */
export async function generate(): Promise<Record<string, string>> {
  const openApi = buildOpenApi();
  return {
    'docs/reference/configuration.md': renderConfiguration(),
    'docs/reference/cli.md': await renderCli(),
    'docs/reference/errors.md': renderErrors(),
    'docs/reference/facilitator-api.md': renderApi(openApi),
    'docs/public/openapi.json': `${JSON.stringify(openApi, null, 2)}\n`,
  };
}

function renderConfiguration(): string {
  return [
    '<!-- Generated by packages/docs-gen from the zod schemas. Do not edit. -->',
    '',
    '# Configuration',
    '',
    'All services are configured with environment variables. They are validated at startup and',
    'every problem is reported at once (`invalid_config`).',
    '',
    '## Facilitator (`apps/facilitator`)',
    '',
    'Unknown networks in `NETWORKS` and invalid asset ids in `ASSETS_*` are rejected at startup.',
    '',
    renderEnvTable(facilitatorEnvSchema.shape),
    '',
    '## Seller watcher (`apps/watcher`)',
    '',
    'Run one watcher per seller address. It uses the wallet created by `obbyx init` in `OBBYX_HOME`.',
    '',
    renderEnvTable(watcherEnvSchema.shape),
    '',
    '## Demo seller (`apps/demo`)',
    '',
    renderEnvTable(demoEnvSchema.shape),
    '',
    '## CLI (`obbyx`)',
    '',
    '| Variable | Default | Description |',
    '| --- | --- | --- |',
    '| `OBBYX_HOME` | `~/.obbyx` | Wallet directory (keys are stored with mode 0600). |',
    '| `LOG_LEVEL` | `warn` | Logging to stderr. |',
    '',
  ].join('\n');
}

async function renderCli(): Promise<string> {
  const parts = [
    '<!-- Generated by packages/docs-gen from the yargs command definitions. Do not edit. -->',
    '',
    '# CLI reference',
    '',
    'Install: `npm i -g @obbyx/cli` (Node 24+). Every command also prints its section with `--help`.',
    '',
  ];
  for (const path of commandPaths()) {
    parts.push(
      `## ${path.length ? `\`obbyx ${path.join(' ')}\`` : 'obbyx'}`,
      '',
      '```text',
      (await renderHelp(path)).trimEnd(),
      '```',
      '',
    );
  }
  return parts.join('\n');
}
